const listVisibleAncestors = `-- name: ListVisibleAncestors :many
WITH RECURSIVE chain AS (
    SELECT p.id, p.parent_id, 1 AS depth
    FROM pages p WHERE p.id = (SELECT x.parent_id FROM pages x WHERE x.id = $1)
    UNION ALL
    SELECT p.id, p.parent_id, chain.depth + 1
    FROM pages p JOIN chain ON p.id = chain.parent_id
),
roles AS (
    SELECT r.page_id::uuid AS page_id, r.role_rank::int AS role_rank
    FROM effective_page_roles(
        (SELECT workspace_id FROM pages WHERE id = $1), $2::uuid,
        COALESCE((SELECT array_agg(id) FROM chain), '{}'::uuid[])) AS r(page_id, role_rank)
)
SELECT p.id, p.title, p.icon
FROM chain
JOIN pages p ON p.id = chain.id
JOIN roles r ON r.page_id = p.id AND r.role_rank >= 1
ORDER BY chain.depth DESC
`

type ListVisibleAncestorsParams struct {
	PageID uuid.UUID
	UserID uuid.UUID
}

type ListVisibleAncestorsRow struct {
	ID    uuid.UUID
	Title string
	Icon  *string
}

// Ancestors (root first) of a page that the caller can view.
func (q *Queries) ListVisibleAncestors(ctx context.Context, arg ListVisibleAncestorsParams) ([]ListVisibleAncestorsRow, error) {
	rows, err := q.db.Query(ctx, listVisibleAncestors, arg.PageID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListVisibleAncestorsRow{}
	for rows.Next() {
		var i ListVisibleAncestorsRow
		if err := rows.Scan(&i.ID, &i.Title, &i.Icon); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

