const listVisibleSubtree = `-- name: ListVisibleSubtree :many
WITH RECURSIVE roles AS MATERIALIZED (
    SELECT r.page_id::uuid AS page_id, r.role_rank::int AS role_rank
    FROM effective_page_roles($1::uuid, $2::uuid) AS r(page_id, role_rank)
    WHERE r.role_rank >= 1
),
sub AS (
    SELECT p.id, 0 AS depth FROM pages p JOIN roles r ON r.page_id = p.id WHERE p.id = $3
    UNION ALL
    SELECT c.id, sub.depth + 1
    FROM pages c
    JOIN sub ON c.parent_id = sub.id
    JOIN roles r ON r.page_id = c.id
    WHERE c.archived_at IS NULL
)
SELECT sub.id FROM sub ORDER BY sub.depth, sub.id
`

type ListVisibleSubtreeParams struct {
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
	RootID      uuid.UUID
}

// ---------------------------------------------------------------- duplicate
// Page ids of the subtree of @root_id that the caller can view (invisible nodes prune their subtree).
// Parents come before children.
func (q *Queries) ListVisibleSubtree(ctx context.Context, arg ListVisibleSubtreeParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listVisibleSubtree, arg.WorkspaceID, arg.UserID, arg.RootID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockWorkspaceTree = `-- name: LockWorkspaceTree :exec
SELECT pg_advisory_xact_lock(hashtext('hostidian:tree:' || $1::text))
`

// Serializes tree-shape changes (moves) inside a workspace so two concurrent moves cannot each pass
// the cycle check and then create a loop together.
func (q *Queries) LockWorkspaceTree(ctx context.Context, workspaceID string) error {
	_, err := q.db.Exec(ctx, lockWorkspaceTree, workspaceID)
	return err
}

