const restoreSubtree = `-- name: RestoreSubtree :many
WITH RECURSIVE sub AS (
    SELECT p0.id FROM pages p0 WHERE p0.id = $2
    UNION ALL
    SELECT c.id FROM pages c JOIN sub ON c.parent_id = sub.id WHERE c.archived_at = $1
)
UPDATE pages SET archived_at = NULL, updated_at = now()
WHERE pages.id IN (SELECT sub.id FROM sub) AND pages.archived_at = $1
RETURNING id
`

type RestoreSubtreeParams struct {
	ArchivedAt *time.Time
	ID         uuid.UUID
}

// Un-archives exactly the rows of the subtree that carry the same archived_at as the target.
func (q *Queries) RestoreSubtree(ctx context.Context, arg RestoreSubtreeParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, restoreSubtree, arg.ArchivedAt, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

